void WriteFields(CStream_AC* aStream) const;	virtual long GetValue() const;		// Returns the current value by getting the CPascalStr_AC and converting it to a number.	virtual void SetValue(long newValue, bool redraw);		// Sets the current value by converting the number to a CPascalStr_AC and then calling SetText.	virtual long GetValidationError();		// Does a range check on the number and if it is out of range returns the        // appropriate error code.	//------------------------------------------------------------------------------------	// data members	//------------------------------------------------------------------------------------public:	long fMinimum;	long fMaximum;};EXPORT_MA  void InitUNumberText();#endif/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		04/17/96	InitUIconSuite		04/15/96	Phase 1 of View Breakup changes		----- Release 10 -----*/